R=[]
R.append((3817119,"एप्पल बेक्ड ओट्स","ये एप्पल बेक्ड ओट्स विशेष अवसरों के लिए एक पौष्टिक व्यंजन हैं जो पोटैशियम में कम हैं।","6",None,
["140g पोरिज ओट्स","1 छोटा चम्मच बेकिंग पाउडर","1 पका केला","100ml दूध (या डेयरी विकल्प)","1 बड़ा अंडा","2 बड़े चम्मच एगेव सिरप (या मेपल सिरप)","1 छोटा चम्मच वनीला एसेंस","2 छोटे चम्मच दालचीनी","1 सेब, कटा हुआ",["परोसने के लिए","60g सादा दही"],["परोसने के लिए","10g सूखा नारियल, भुना हुआ"],["वैकल्पिक","250g पका हुआ फल (बिना अतिरिक्त चीनी के) जैसे नाशपाती या सेब"],["वैकल्पिक","या 400g डिब्बाबंद फल (रस में डिब्बाबंद, रस फेंक दें), जैसे आड़ू या नाशपाती"]],
["ओवन को 180°C / 160°C फ़ैन / गैस मार्क 4 पर पहले से गरम करें। एक ओवन-सेफ़ डिश में हल्का तेल लगाएँ। ओट्स और बेकिंग पाउडर को ब्लेंडर में डालें और पिसने तक चलाएँ।","केला, दूध, अंडा, एक बड़ा चम्मच सिरप, वनीला एसेंस और दालचीनी को ब्लेंडर में डालें और चिकना और पूरी तरह मिलने तक ब्लेंड करें। ओवन डिश में डालें।","कटे हुए सेब को बचे हुए एक बड़े चम्मच सिरप के साथ मिलाएँ और डिश के ऊपर सजाएँ। 25 मिनट बेक करें।","ओवन से निकालें और कुछ देर ठंडा होने दें। ऊपर एक चम्मच दही और भुना हुआ नारियल छिड़ककर और चाहें तो वैकल्पिक फल के साथ छह हिस्सों में परोसें।"],
[[CH,"इस रेसिपी को तैयार करना बहुत जल्दी है। यह मिठाई हो सकती है या किसी विशेष अवसर पर नाश्ते के रूप में भी खाई जा सकती है।"],[CB,"इस मिठाई में ओट्स और सिरप कार्बोहाइड्रेट के मुख्य स्रोत हैं और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"यह मिठाई पोटैशियम में कम है, इसलिए विशेष अवसरों पर उन लोगों के लिए उपयुक्त है जिन्हें कम पोटैशियम वाला आहार लेने की सलाह दी गई है।\nयह रेसिपी ओट्स और बेकिंग पाउडर के कारण फ़ॉस्फ़ेट में अधिक है। यदि आपको कम फ़ॉस्फ़ेट वाला आहार लेने की सलाह दी गई है तो इस रेसिपी को बनाने की आवृत्ति सीमित रखना सबसे अच्छा हो सकता है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"यह रेसिपी प्रोटीन में कम है, जो इसे उन लोगों के लिए उपयुक्त बनाती है जिन्हें कम प्रोटीन खाने की सलाह दी गई है।"],[GF,"ग्लूटेन-मुक्त ओट्स का उपयोग करें।"],[HO,"आप कम वसा या घटी हुई वसा वाले दही या ओट या सोया दही जैसे पौधे-आधारित विकल्प का उपयोग करने पर विचार कर सकते हैं। सुझाए अनुसार आप इसे सेब और नाशपाती जैसे पके हुए फल, या आड़ू और नाशपाती जैसे डिब्बाबंद फल के साथ परोसना भी चाह सकते हैं।"],[ST,"फ्रिज में तीन दिन तक रखें और परोसने से पहले दोबारा गरम करें।"]],
[]))
R.append((3817521,"फूलगोभी और केल नूडल्स","फ़ाइबर से भरपूर, यह रेसिपी एक बेहतरीन पेट भरने वाला भोजन बनाती है।","4",None,
[["ड्रेसिंग","2 नीबू या 1 नींबू का रस"],["ड्रेसिंग","2 बड़े चम्मच जैतून का तेल"],["ड्रेसिंग","3 बड़े चम्मच कम नमक वाली सोया सॉस"],["ड्रेसिंग","अँगूठे जितना बड़ा ताज़ा अदरक का टुकड़ा, छिला और बारीक कद्दूकस किया हुआ"],["ड्रेसिंग","स्वादानुसार सूखी मिर्च के फ़्लेक्स"],["ड्रेसिंग","2 लहसुन की कलियाँ, कुचली / बारीक कटी हुई"],["ड्रेसिंग","1 छोटा चम्मच मेपल सिरप या शहद"],["ड्रेसिंग","1 छोटा चम्मच भुना हुआ तिल का तेल"],["नूडल्स","2 बड़े चम्मच जैतून या वनस्पति तेल"],["नूडल्स","1 मध्यम फूलगोभी, पत्तियों सहित"],["नूडल्स","200g कावोलो नेरो या केल, डंठल हटाए हुए और पत्तियाँ बारीक कटी हुई"],["नूडल्स","250g साबुत गेहूँ के नूडल्स"],["परोसने के लिए","4 अंडे"],["परोसने के लिए","50g काजू"],["परोसने के लिए","4 बड़े चम्मच किमची"]],
["ओवन को 200°C/ 180°C फ़ैन/ गैस मार्क 6 पर पहले से गरम करें। फूलगोभी की खराब पत्तियाँ और डंठल काट दें, उसे बहते ठंडे पानी में धोएँ, फिर मुख्य फूलगोभी को फूलों में और पत्तियों को टुकड़ों में काटें। फूलों और पत्तियों को 1 बड़े चम्मच वनस्पति तेल में मिलाएँ और 30 मिनट भूनने के लिए ओवन में रखें, 15 मिनट बाद चलाएँ।","ड्रेसिंग की सभी सामग्री को एक खाली, साफ़ जैम के जार में डालें और अच्छी तरह हिलाएँ।","एक बड़े बर्तन में पानी उबालें और उबलने पर नूडल्स डालें और पैकेट के निर्देशों के अनुसार पकाएँ (आमतौर पर लगभग 4-5 मिनट)। अच्छी तरह पानी निथारें और एक तरफ़ रख दें।","एक बड़े फ्राइंग पैन में बचा हुआ 1 बड़ा चम्मच वनस्पति तेल मध्यम-तेज़ आँच पर गरम करें और फिर कावोलो नेरो या केल डालें। लगातार चलाते हुए लगभग 4 मिनट नरम होने तक पकाएँ।","पके हुए नूडल्स और फूलगोभी को कावोलो नेरो या केल वाले पैन में डालें और ऊपर से ड्रेसिंग डालें। ड्रेसिंग से लपेटने के लिए अच्छी तरह चलाएँ। सब कुछ गरम होने तक कुछ मिनट पकाएँ।","यदि काजू के साथ परोस रहे हैं, तो एक छोटे फ्राइंग पैन को मध्यम आँच पर गरम करें (बिना तेल के) और काजू डालें। उन्हें लगभग तीन मिनट भुनने तक पकाएँ, पैन को बार-बार हिलाएँ ताकि वे जलें नहीं। यदि आप अंडे ले रहे हैं, तो नूडल्स, कावोलो नेरो या केल और फूलगोभी के पकने के दौरान उन्हें पोच करें या तलें। परोसने के लिए, नूडल्स, फूलगोभी और कावोलो नेरो या केल को प्लेट में सजाएँ, ऊपर एक अंडा रखें, कुछ काजू छिड़कें और यदि उपयोग कर रहे हों तो एक बड़ा चम्मच किमची डालें।"],
[[CH,"एक स्वादिष्ट, ज़ायकेदार और हल्के मसाले वाला भोजन।"],[CB,"इस व्यंजन में नूडल्स कार्बोहाइड्रेट का मुख्य स्रोत हैं और ये मान उन लोगों के लिए दिए गए हैं "+INS],[PP,"मेवों में आमतौर पर पोटैशियम और फ़ॉस्फ़ेट अधिक होते हैं लेकिन आप अतिरिक्त कुरकुरेपन के लिए इस रेसिपी में थोड़ी मात्रा में काजू का उपयोग कर सकते हैं। नूडल्स में पोटैशियम कम होता है, जिससे इस भोजन में बिना उबाली सब्ज़ियाँ डाली जा सकती हैं।\nयदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"यह रेसिपी कम प्रोटीन वाले भोजन के मानदंड को पूरा करती है। यदि आपकी प्रोटीन की ज़रूरत अधिक है तो आप और अंडा मिला सकते हैं, लेकिन तब यह कम फ़ॉस्फ़ेट वाला व्यंजन नहीं रहेगा।"],[GF,"ग्लूटेन-मुक्त नूडल्स (जैसे बकव्हीट या राइस नूडल्स) और सोया सॉस की जगह टैमारी का उपयोग करें (यदि संभव हो तो कम नमक वाली चुनें)।"],[VT,"जाँच लें कि किमची मछली या शेलफ़िश से नहीं बनी है।"],[VG,"अंडा न डालें और ड्रेसिंग में शहद की जगह मेपल सिरप का उपयोग करें। यदि किमची का उपयोग कर रहे हों तो उसकी सामग्री जाँचें।"],[CO,"सामान्य नूडल्स चुनें और किमची और काजू जैसे महँगे वैकल्पिक अतिरिक्त पदार्थ छोड़ दें।"],[ST,"ड्रेसिंग को फ्रिज में दो दिन तक रखा जा सकता है। बचे हुए को ढककर फ्रिज में दो दिन तक रखा जा सकता है और ठंडा खाया जा सकता है या दोबारा गरम किया जा सकता है।"],[TP,"कई चरण पहले से किए जा सकते हैं: फूलगोभी को भूना जा सकता है, ड्रेसिंग बनाई जा सकती है और कावोलो नेरो को पकाने के लिए तैयार किया जा सकता है, यानी जब आप खाना चाहें तो बस नूडल्स पकाएँ, कावोलो नेरो पकाएँ और सब कुछ गरम करने के लिए पहले से पकी फूलगोभी और ड्रेसिंग डाल दें।"]],
[]))
R.append((3825469,"बीफ़ स्टर फ़्राई","यह व्यंजन प्रोटीन में अधिक है इसलिए डायलिसिस ले रहे व्यक्ति के लिए उपयुक्त रात का भोजन होगा।","4",None,
["500g बीफ़ स्टेक, रंप या सिरलोइन","1 हरी शिमला मिर्च","4 हरे प्याज़","1-2 लहसुन की कलियाँ, कुचली हुई","4 अजवाइन की डंठल (सेलेरी)","1 लाल शिमला मिर्च","2-3 छोटे चम्मच हल्की लाल मिर्च पाउडर","2 बड़े चम्मच पैपरिका","1 बहुत कम नमक वाला या बिना नमक का बीफ़ स्टॉक क्यूब","60ml उबलता पानी","2 बड़े चम्मच साफ़ शहद","2 बड़े चम्मच रेड वाइन सिरका","2 बड़े चम्मच सूरजमुखी तेल","1 बड़ा चम्मच वूस्टरशायर सॉस","250g कच्चे बासमती चावल, धुले और पानी निथारे हुए।"],
["बीफ़ को 1cm की पट्टियों में काटें और कटोरे में रखें। पैपरिका और लाल मिर्च पाउडर डालें, बीफ़ पर बराबर लगाएँ। 1 घंटे के लिए मैरिनेट होने दें। 30 मिनट बाद चलाएँ और देखें कि बीफ़ पर मसाला अच्छी तरह लगा है।","चावल को सॉसपैन में डालें और 500ml पानी डालें। तेज़ उबाल आने दें और आँच धीमी करके हल्की उबाल पर रखें। 12 मिनट पकाएँ।","सेलेरी और शिमला मिर्च को 5 cm की लंबाई में और फिर लगभग 5 mm मोटी पट्टियों में काटें। हरे प्याज़ को पतला काटकर एक तरफ़ रख दें।","कड़ाही या बड़े फ्राइंग पैन में तेल गरम करें और हरे प्याज़, लहसुन, सेलेरी और शिमला मिर्च को एक मिनट तलें, फिर स्टेक डालें। तेज़ आँच पर 3-4 मिनट तलना जारी रखें।","एक स्टॉक क्यूब को 60ml उबलते पानी में डालकर और वूस्टरशायर सॉस, शहद और रेड वाइन सिरका मिलाकर सॉस बनाएँ। सॉस डालें और मांस पर अच्छी तरह लगने तक पकाएँ।","चावल का पानी निथारें और उबलते पानी से धोएँ, तुरंत परोसें।"],
[[CH,"कोमल बीफ़ के साथ यह स्वादिष्ट, एशियाई-प्रेरित स्टर फ़्राई झटपट बनाएँ। व्यस्त सप्ताह के रात के खाने के लिए या पहले से बनाकर फ़्रीज़ करने के लिए एकदम सही।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट का मुख्य स्रोत चावल है। हालाँकि, शहद भी इस भोजन के कार्बोहाइड्रेट में योगदान देगा। कार्बोहाइड्रेट के मान उन लोगों के लिए दिए गए हैं "+INS],[PP,BIND],[PR,"यह रेसिपी प्रोटीन में बहुत अधिक है जो डायलिसिस वाले लोगों के लिए बहुत अच्छी है। यदि आपको प्रोटीन का सेवन घटाने की सलाह दी गई है, तो बीफ़ का छोटा हिस्सा लें।"],[GF,"ग्लूटेन-मुक्त स्टॉक क्यूब का उपयोग करें और चावल के साथ परोसें।"],[VT,"शाकाहारी आहार के अनुकूल बनाने के लिए बीफ़ की जगह टोफ़ू या क्वॉर्न के टुकड़ों जैसा शाकाहारी प्रोटीन उपयोग किया जा सकता है।"],[VG,"बीफ़ की जगह टोफ़ू या वीगन विकल्प डालें, शहद न डालें और उसकी जगह एक बड़ा चम्मच गोल्डन सिरप का उपयोग करें।"],[CO,"समान रूप से स्वादिष्ट लेकिन सस्ते व्यंजन के लिए बीफ़ की जगह टर्की या टोफ़ू उपयोग करें।"],[ST,"बचे हुए बीफ़ स्टर फ़्राई को फ़्रीज़ करें लेकिन हम चावल को फ़्रीज़ करने की सलाह नहीं देते। पिघलाने के लिए, डिब्बे का ढक्कन हटाएँ और धीरे-धीरे पिघलने के लिए फ्रिज में रखें। इसे अपनी कड़ाही, फ्राइंग पैन या माइक्रोवेव में अच्छी तरह दोबारा गरम करें।"]],
[]))
R.append((3853426,"बीन स्टू",">","2",None,
["100g गाजर, छिली और कटी हुई","1 कम नमक वाला सब्ज़ी स्टॉक क्यूब, 300ml उबलते पानी से बना हुआ","400g का सफ़ेद फलियों का डिब्बा (कोई भी प्रकार) धोया और पानी निथारा हुआ","2 बड़े चम्मच टमाटर प्यूरी","1 छोटा चम्मच सूखी मिश्रित जड़ी-बूटियाँ","100g जमी हुई मटर",["परोसने के लिए","काली मिर्च"],["परोसने के लिए","50g कद्दूकस किया हुआ चेडर चीज़"],["परोसने के लिए","ब्रेड के 2 मोटे स्लाइस या 2 कुरकुरे रोल"]],
["गाजर को बर्तन में रखें और उबलते स्टॉक से ढकें। 4 मिनट धीमी आँच पर पकाएँ।","पानी निथारी हुई फलियाँ, टमाटर प्यूरी और मिश्रित जड़ी-बूटियाँ डालें और चलाएँ।","आँच धीमी करें और 20 मिनट पकाएँ, फिर जमी हुई मटर डालें और 3-5 मिनट और पकाएँ।","2 कटोरों में ब्रेड के साथ परोसें और काली मिर्च डालें। ऊपर से कद्दूकस किया हुआ चीज़ छिड़कें।"],
[[CH,"एक पौष्टिक, उच्च प्रोटीन वाला शाकाहारी व्यंजन जो पोटैशियम और फ़ॉस्फ़ेट में भी कम है।"],[CB,"इस मुख्य भोजन में ब्रेड कार्बोहाइड्रेट का मुख्य स्रोत है, हालाँकि फलियाँ भी कार्बोहाइड्रेट का स्रोत होंगी। यह मान उन लोगों के लिए दिया गया है "+INS],["पोटैशियम/फ़ॉस्फ़ेट","यह व्यंजन पोटैशियम में कम है; यदि आपको कम पोटैशियम वाला आहार लेने की सलाह दी गई है, तो बताई गई मात्रा का पालन करना सुनिश्चित करें। यह रेसिपी फ़ॉस्फ़ेट में कम है, हालाँकि फलियों और चीज़ के कारण इसमें कुछ फ़ॉस्फ़ेट होता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो कृपया इस व्यंजन के साथ उन्हें लेना सुनिश्चित करें।"],[PR,"यह व्यंजन प्रोटीन में अधिक है और इसलिए डायलिसिस ले रहे लोगों के लिए उपयुक्त है। यदि आपको कम प्रोटीन खाने की सलाह दी गई है तो आप मटर की जगह स्वीटकॉर्न ले सकते हैं और/या चीज़ की मात्रा घटाकर 30g कर सकते हैं।"]],
[]))
R.append((3905574,"सॉते की हुई सब्ज़ियों के साथ कैरिबियाई ओवन बेक्ड सैल्मन","कम पोटैशियम और कम फ़ॉस्फ़ेट वाली रेसिपी जिसमें मसालेदार तीखापन है। संतुलित भोजन बनाने के लिए चावल के साथ परोसें।","4",None,
[["सैल्मन","4 सैल्मन फ़िलेट (प्रत्येक लगभग 120g)"],["सैल्मन","1 नींबू"],["सैल्मन","1 अजवाइन की डंठल (सेलेरी)"],["सैल्मन","250g सफ़ेद पत्तागोभी"],["सैल्मन","½ हरी शिमला मिर्च"],["सैल्मन","½ लाल शिमला मिर्च"],["सैल्मन","½ पीली शिमला मिर्च"],["सैल्मन","1 गाजर"],["सैल्मन","2 बड़े चम्मच वनस्पति तेल"],["कैरिबियाई ग्रीन सीज़निंग","2 हरे प्याज़, छँटे हुए"],["कैरिबियाई ग्रीन सीज़निंग","1 स्कॉच बोनेट मिर्च"],["कैरिबियाई ग्रीन सीज़निंग","3 लहसुन की कलियाँ"],["कैरिबियाई ग्रीन सीज़निंग","मुट्ठी भर ताज़ा थाइम या नींबू थाइम"],["कैरिबियाई ग्रीन सीज़निंग","मुट्ठी भर ताज़ा धनिया"],["कैरिबियाई ग्रीन सीज़निंग","मुट्ठी भर ताज़ा तुलसी"],["कैरिबियाई ग्रीन सीज़निंग","1 बड़ा प्याज़, छिला और कटा हुआ"],["कैरिबियाई ग्रीन सीज़निंग","1 अजवाइन की डंठल (सेलेरी), कटी हुई"]],
["कैरिबियाई ग्रीन सीज़निंग बनाने के लिए हरे प्याज़, स्कॉच बोनेट, लहसुन, थाइम, धनिया, तुलसी, प्याज़ और सेलेरी को फ़ूड प्रोसेसर में एक साथ ब्लेंड करें। सैल्मन को कटोरे में रखें और नींबू से साफ़ करें। 2 बड़े चम्मच सीज़निंग डालें और मिलाएँ। इसे पकाने से पहले रात भर या कम से कम एक घंटे के लिए फ्रिज में रहने दें।","ओवन को 190°C/ 170°C फ़ैन /गैस मार्क 5 पर गरम करें। सैल्मन को चिकनाई लगे बेकिंग टिन में रखें और ऊपर थोड़ा तेल डालें। फ़ॉइल से ढकें और 20 मिनट पकाएँ। एक बड़े सॉसपैन को पानी से भरें और उबालें। सेलेरी, सफ़ेद पत्तागोभी, शिमला मिर्च और गाजर को बारीक काटकर अपनी सब्ज़ियाँ तैयार करें।","सैल्मन पर लगी फ़ॉइल हटाएँ और फिर 10 मिनट और पकाएँ जब तक वह थोड़ा भूरा न हो जाए। इन आखिरी 10 मिनट के दौरान, कटी हुई सब्ज़ियों को खूब पानी में थोड़ा नरम होने तक उबालें और फिर पानी निथार दें।","उबली हुई सब्ज़ियों को फ्राइंग पैन में 2 बड़े चम्मच तेल में 3 मिनट सॉते करें, स्वाद के लिए थोड़ी कैरिबियाई सीज़निंग डालें। सैल्मन को सॉते की हुई सब्ज़ियों की परत पर परोसें।"],
[[CH,"कैरिबियाई ग्रीन सीज़निंग एक बहुमुखी सॉस या पेस्ट है जिसका उपयोग अक्सर कैरिबियाई द्वीपों में किया जाता है। मछली को मैरिनेट करें और खूब स्वाद भरने के लिए सब्ज़ियों में डालें।"],[CB,"इस रेसिपी में कार्बोहाइड्रेट कम है और मान उन लोगों के लिए दिए गए हैं "+INS+" इसे अधिक संतुलित भोजन बनाने के लिए चावल या कॉर्नमील पाई के छोटे हिस्से के साथ परोसें।"],[PP,"यहाँ उपयोग की गई बिना हड्डी की मछली फ़ॉस्फ़ेट को कम रखने में मदद करती है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें। सब्ज़ियों को पहले उबालने से उनका पोटैशियम घटता है। यदि आपको कम पोटैशियम वाले आहार की ज़रूरत नहीं है तो आप सब्ज़ियों को कच्चा ही सॉते कर सकते हैं। ग्रीन सीज़निंग में कच्ची सामग्री होती है और इसलिए इसमें पोटैशियम अधिक होता है इसलिए इसे केवल थोड़ी मात्रा में उपयोग करना चाहिए।"],[PR,"मछली प्रोटीन का बेहतरीन कम वसा वाला स्रोत है। इस व्यंजन के साथ सी ब्रीम या सी बास के फ़िलेट भी विकल्प के रूप में अच्छे रहते हैं।"],[CO,"लागत कम करने के लिए आप जमी हुई मछली उपयोग कर सकते हैं (पकाने से पहले फ्रिज में अच्छी तरह पिघलाएँ)।"],[ST,"यदि आप ग्रीन सीज़निंग में एक बड़ा चम्मच सेब का सिरका मिलाते हैं तो इसे पहले से बनाकर फ्रिज में पाँच दिन तक रखा जा सकता है।"],[TP,"यदि आपको तीखा पसंद है तो अपनी कैरिबियाई ग्रीन सीज़निंग में 2 स्कॉच बोनेट मिर्चें डालें!\nयदि आपका प्रत्यारोपण हुआ है तो बैक्टीरिया के संदूषण के किसी भी जोखिम से बचने के लिए आपको मछली मछली बेचने वाले या फ़िश डेली काउंटर से लेने के बजाय पहले से पैक की हुई खरीदनी चाहिए।"]],
[]))
R.append((3915498,"चिकन और शिमला मिर्च वन पॉट",">","2",None,
["2 चिकन जाँघें (150-160g), त्वचा निकाली हुई","1 डेज़र्ट स्पून (10ml) जैतून का तेल","1 लाल शिमला मिर्च, 3cm के टुकड़ों में कटी हुई","1 हरी शिमला मिर्च, 3cm के टुकड़ों में कटी हुई","1 शैलट (छोटा प्याज़), बारीक कटा हुआ","1 लहसुन की कली, कटी हुई","2 लाल मिर्चें, कटी हुई और बीज निकाली हुई","150g ऑरज़ो पास्ता","1 डेज़र्ट स्पून (10ml) मीठी पैपरिका","250ml कम नमक वाला चिकन स्टॉक","75g चेरी टमाटर","काली मिर्च","छोटी मुट्ठी भर अजमोद (पार्सले), कटा हुआ (वैकल्पिक)","10g क्रेम फ्रेश (वैकल्पिक)"],
["ओवन को 190°C / फ़ैन 170°C / गैस मार्क 5 पर पहले से गरम करें। एक आँच-रोधी कैसरोल डिश में जैतून का तेल डालें और चूल्हे पर मध्यम आँच पर रखें। चिकन पर काली मिर्च छिड़कें और हर तरफ़ से सील होने तक पकाएँ। बाद के लिए एक प्लेट में रख दें।","शिमला मिर्च को डिश में डालें और 3 से 4 मिनट पकाएँ, फिर शैलट, लहसुन और मिर्चें डालें। नरम होने तक 5 मिनट और पकाएँ। ऑरज़ो और पैपरिका मिलाएँ।","ऊपर से स्टॉक और ऑरज़ो को पूरी तरह ढकने के लिए अतिरिक्त 200ml उबलता पानी डालें। चिकन और टमाटर को ऑरज़ो के ऊपर रखें और ओवन में 30 मिनट बेक करें।","कटोरों में परोसें, चाहें तो ऊपर क्रेम फ्रेश और कटा हुआ अजमोद डालें।"],
[[CH,"एक आसान, सप्ताह के बीच के दिनों के रात के खाने का व्यंजन, किडनी रोग के सभी चरणों के लिए उपयुक्त।"],[CB,"इस रेसिपी में ऑरज़ो (पास्ता) कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"सामग्री की मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। यह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से चिकन से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन में अधिक है, इसलिए उन लोगों के लिए उपयुक्त है जिन्हें अधिक प्रोटीन खाने की सलाह दी गई है, जैसे डायलिसिस ले रहे लोग। यदि आपको कम प्रोटीन खाने की सलाह दी गई है, तो आप चिकन घटाकर छोले का एक डिब्बा मिला सकते हैं। इससे पोटैशियम और फ़ॉस्फ़ेट की मात्रा भी घटेगी।"],[ST,FRESH],[TP,"यदि आपके सुपरमार्केट में ऑरज़ो नहीं मिलता है तो उसकी जगह कच्चे चावल का उपयोग किया जा सकता है।"]],
[]))
